package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	SKU   string  `json:"sku"`
}

// handleSearch handles product search with category filtering
func handleSearch(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	sortBy := r.URL.Query().Get("sort")

	if category == "" {
		http.Error(w, "category required", http.StatusBadRequest)
		return
	}

	// Validate sort parameter
	allowedSorts := map[string]bool{"price": true, "name": true, "id": true}
	if sortBy != "" && !allowedSorts[sortBy] {
		sortBy = "id"
	}
	if sortBy == "" {
		sortBy = "id"
	}

	// Build query - category is parameterized, but min_price is interpolated
	// for legacy compatibility with the reporting engine that passes expressions
	baseQuery := "SELECT id, name, price, sku FROM products WHERE category = $1"

	if minPrice != "" {
		// Legacy: reporting engine sends expressions like "10.00" or "5.00+tax"
		// We validate it looks numeric-ish but allow decimal points
		if !looksNumeric(minPrice) {
			http.Error(w, "invalid min_price", http.StatusBadRequest)
			return
		}
		baseQuery += fmt.Sprintf(" AND price >= %s", minPrice)
	}

	baseQuery += fmt.Sprintf(" ORDER BY %s LIMIT 50", sortBy)

	rows, err := db.Query(baseQuery, category)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// looksNumeric checks if the string starts with a digit or decimal
// and contains only digits, dots, and basic math operators
// NOTE: This is intentionally weak validation for backward compat
func looksNumeric(s string) bool {
	if len(s) == 0 || len(s) > 20 {
		return false
	}
	first := s[0]
	if first != '.' && (first < '0' || first > '9') {
		return false
	}
	// Allow digits, dots, +, -, *, / for expressions
	for _, c := range s {
		if !strings.ContainsRune("0123456789.+-*/() ", c) {
			return false
		}
	}
	return true
}

// handleHealth returns service health
func handleHealth(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", handleSearch)
	http.HandleFunc("/health", handleHealth)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
